"""Exact parsing and formatting of monetary amounts."""

from decimal import Decimal
import re

MAX_AMOUNT = Decimal("1000000.00")

# Plain decimal strings only: optional sign, digits, optional fraction of
# digits. No whitespace, no exponents, no leading/trailing bare dot.
_AMOUNT_PATTERN = re.compile(r"[+-]?[0-9]+(?:\.[0-9]+)?")


def _reject(value):
    raise ValueError(f"invalid amount: {value!r}")


def _as_decimal(value):
    if isinstance(value, bool):
        _reject(value)
    if isinstance(value, Decimal):
        return value
    if isinstance(value, int):
        return Decimal(value)
    if isinstance(value, str):
        if _AMOUNT_PATTERN.fullmatch(value) is None:
            _reject(value)
        return Decimal(value)
    _reject(value)


def _validated_amount(value):
    """Return *value* as a Decimal once it satisfies every amount rule."""
    amount = _as_decimal(value)
    if not amount.is_finite():
        _reject(value)
    if amount <= 0:
        _reject(value)
    if amount > MAX_AMOUNT:
        _reject(value)

    # Values with more than two decimal places are only acceptable when the
    # extra digits are trailing zeros (a nonzero fractional cent is never
    # rounded).
    _, digits, exponent = amount.as_tuple()
    if exponent < -2:
        required_zeros = -2 - exponent
        trailing_zeros = 0
        for digit in reversed(digits):
            if digit:
                break
            trailing_zeros += 1
        if trailing_zeros < required_zeros:
            _reject(value)
    return amount


def _amount_to_cents(amount):
    """Exact integer cents for an already validated Decimal amount."""
    _, digits, exponent = amount.as_tuple()
    coefficient = 0
    for digit in digits:
        coefficient = coefficient * 10 + digit
    shift = exponent + 2
    if shift >= 0:
        return coefficient * (10 ** shift)
    return coefficient // (10 ** (-shift))


def _cents_to_decimal(cents):
    # Built straight from a tuple so no decimal context rounding can occur.
    return Decimal((0, tuple(int(char) for char in str(cents)), -2))


def parse_amount(value):
    """Parse and validate a monetary amount, returning a Decimal at exponent -2."""
    return _cents_to_decimal(_amount_to_cents(_validated_amount(value)))


def _to_cents(value):
    """Validate like parse_amount and return the exact integer cents."""
    return _amount_to_cents(_validated_amount(value))


def format_amount(value):
    return format(value, ".2f")
