"""Extended checks for exact money parsing and invoice rules.

Runnable directly (``python3 checks/test_rules.py``) or via pytest.
"""

import decimal
import os
import sys
from decimal import Decimal

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

from src.money import format_amount, parse_amount  # noqa: E402
from src.api import make_invoice  # noqa: E402


def _raises_value_error(func, value):
    try:
        func(value)
    except ValueError:
        return True
    return False


def test_valid_amounts():
    cases = [
        (Decimal("12.34"), "12.34"),
        (Decimal("1.2300"), "1.23"),
        (Decimal("1000000.00"), "1000000.00"),
        (5, "5.00"),
        ("12.50", "12.50"),
        ("+1.2", "1.20"),
        ("1.2300", "1.23"),
        ("0.01", "0.01"),
        ("00001.20", "1.20"),
        ("1000000.000", "1000000.00"),
    ]
    for value, expected in cases:
        parsed = parse_amount(value)
        assert isinstance(parsed, Decimal)
        assert parsed.as_tuple().exponent == -2
        assert format_amount(parsed) == expected


def test_invalid_amounts():
    cases = [
        1.0, 1.23, True, False, None, [], {}, object(),
        Decimal("NaN"), Decimal("sNaN"), Decimal("Infinity"),
        Decimal("0"), Decimal("-1"), Decimal("0.00"), Decimal("-0.00"),
        Decimal("1000000.01"), Decimal("1.005"), Decimal("1.2340"),
        0, -1, 1000001,
        "", " ", "1.00 ", " 1.00", "1e2", "1E2", "abc", "NaN", "Infinity",
        "1,000", "1_000", ".5", "5.", "-1", "-0.00", "0", "0.00", "+0",
        "1000000.01", "1000000.001", "1.005", "0.005", "1.000001",
    ]
    for value in cases:
        assert _raises_value_error(parse_amount, value), value


def test_max_and_trailing_zeros():
    assert format_amount(parse_amount("999999.9900")) == "999999.99"
    assert format_amount(parse_amount(Decimal("1E+6"))) == "1000000.00"


def test_invoice_basics():
    assert make_invoice([]) == {"total": "0.00", "count": 0}
    assert make_invoice(["1.20", "2.30"]) == {"total": "3.50", "count": 2}
    assert make_invoice(["1.20", 2, Decimal("0.30")]) == {
        "total": "3.50", "count": 3,
    }
    assert make_invoice(["999999.99", "0.01"]) == {
        "total": "1000000.00", "count": 2,
    }


def test_invoice_rejects_invalid_items_and_totals():
    assert _raises_value_error(make_invoice, ["1000000.00", "0.01"])
    assert _raises_value_error(make_invoice, [1.0])
    assert _raises_value_error(make_invoice, [True])
    assert _raises_value_error(make_invoice, [0])
    assert _raises_value_error(make_invoice, ["1.005"])


def test_invoice_rejects_non_list_inputs():
    for value in (None, 5, 1.2, "1.20", {"a": 1}, {}):
        assert _raises_value_error(make_invoice, value), value


def test_invoice_does_not_mutate_input():
    amounts = ["1.20", Decimal("2.30")]
    snapshot = list(amounts)
    make_invoice(amounts)
    assert amounts == snapshot


def test_decimal_context_untouched():
    context = decimal.getcontext()
    before = (context.prec, context.rounding, dict(context.traps), dict(context.flags))
    context.prec = 1
    try:
        assert format_amount(parse_amount("1.23")) == "1.23"
        assert make_invoice(["1.20", "2.30"]) == {"total": "3.50", "count": 2}
    finally:
        context.prec = before[0]
    after = (context.prec, context.rounding, dict(context.traps), dict(context.flags))
    assert before == after


if __name__ == "__main__":
    for name, func in sorted(globals().items()):
        if name.startswith("test_") and callable(func):
            func()
    print("checks/test_rules.py: all checks passed")
